begin;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000991'),('00000000-0000-4000-8000-000000000992');
insert into public.profiles(id) values('00000000-0000-4000-8000-000000000991'),('00000000-0000-4000-8000-000000000992');
insert into vault.decrypted_secrets(name,decrypted_secret) values('djen_cron_secret','placeholder-exclusivo-banco-descartavel');
do $$declare cfg jsonb:='{"nome":"Analista personalizado","missao":"Priorizar","cargo":"Analista","sala":"operacional","prompt_base":"Use orientações da base para analisar.","tom":"formal","ferramentas":["indicadores_operacionais","base_conhecimento"],"documentos":[{"id":"a","titulo":"Manual","texto":"Orientação interna original"}],"intervalo_minutos":null,"ativo":false}'; a uuid; b uuid; r jsonb; w uuid; n integer;
begin
 if has_function_privilege('authenticated','public.escritorio_salvar_config(uuid,uuid,integer,jsonb)','execute') or has_function_privilege('anon','public.escritorio_ler_config(uuid,uuid)','execute') then raise exception 'Configuração privada exposta';end if;
 r:=public.escritorio_salvar_config('00000000-0000-4000-8000-000000000991',null,0,cfg);a:=(r->>'agente_id')::uuid;
 if (select ativo from public.agentes_ia where id=a) then raise exception 'Ativação implícita';end if;
 if (public.escritorio_ler_config('00000000-0000-4000-8000-000000000991',a)->>'revisao')::integer<>1 then raise exception 'Versão inicial ausente';end if;
 begin perform public.escritorio_ler_config('00000000-0000-4000-8000-000000000992',a);raise exception 'Vazou configuração';exception when insufficient_privilege then null;end;
 perform public.escritorio_salvar_config('00000000-0000-4000-8000-000000000991',a,1,jsonb_set(cfg,'{nome}','"Nova versão"'));
 begin perform public.escritorio_salvar_config('00000000-0000-4000-8000-000000000991',a,1,cfg);raise exception 'Sobrescreveu edição concorrente';exception when serialization_failure then null;end;
 if not exists(select 1 from escritorio_privado.agente_config_historico where agente_id=a and revisao=1 and dados->>'nome'='Analista personalizado') then raise exception 'Perdeu versão anterior';end if;
 begin perform public.escritorio_salvar_config('00000000-0000-4000-8000-000000000991',a,2,jsonb_set(cfg,'{ferramentas}','["enviar_email"]'));raise exception 'Liberou ferramenta inexistente';exception when raise_exception then if sqlerrm='Liberou ferramenta inexistente' then raise;end if;end;
 begin perform public.escritorio_alterar_agente('00000000-0000-4000-8000-000000000992',a,'mover','marketing',null);raise exception 'Moveu agente de outra supervisora';exception when insufficient_privilege then null;end;
 begin perform public.escritorio_alterar_agente('00000000-0000-4000-8000-000000000992',a,'alternar',null,true);raise exception 'Ativou agente de outra supervisora';exception when insufficient_privilege then null;end;
 if (select sala from public.agentes_ia where id=a)<>'operacional' or (select ativo from public.agentes_ia where id=a) then raise exception 'Alteração entre contas';end if;
 perform public.escritorio_alterar_agente('00000000-0000-4000-8000-000000000991',a,'mover','marketing',null);
 if (select sala from public.agentes_ia where id=a)<>'marketing' then raise exception 'Não alterou agente próprio';end if;
 if (public.escritorio_ler_config('00000000-0000-4000-8000-000000000991',a)->>'revisao')::integer<>3 then raise exception 'Mudança de sala não incrementou revisão';end if;
 r:=public.escritorio_salvar_config('00000000-0000-4000-8000-000000000992',null,0,cfg);b:=(r->>'agente_id')::uuid;
 update public.agentes_ia set ativo=true,intervalo_minutos=60,proxima_execucao=now()-interval '1 hour' where id in(a,b);
 w:=(public.escritorio_worker_gerir('00000000-0000-4000-8000-000000000991','criar','Worker fixture',repeat('a',64))->>'id')::uuid;
 if public.escritorio_worker_pulso(w,repeat('b',64),'teste') is not null then raise exception 'Aceitou credencial incorreta';end if;
 r:=public.escritorio_worker_pulso(w,repeat('a',64),'teste');
 if (r->>'despachos_enviados')::integer<>1 then raise exception 'Não limitou à supervisora do worker';end if;
 if (public.escritorio_worker_pulso(w,repeat('a',64),'teste')->>'despachos_enviados')::integer<>0 then raise exception 'Repetiu pulso';end if;
 if (select proxima_execucao<=now() from public.agentes_ia where id=a) then raise exception 'Não avançou a reserva de despacho';end if;
 if not (select proxima_execucao<=now() from public.agentes_ia where id=b) then raise exception 'Despachou agente de outra supervisora';end if;
 if public.escritorio_worker_gerir('00000000-0000-4000-8000-000000000991','listar')::text like '%token_hash%' then raise exception 'Expôs credencial';end if;
 perform public.escritorio_worker_gerir('00000000-0000-4000-8000-000000000991','revogar',null,null,w);
 if public.escritorio_worker_pulso(w,repeat('a',64),'teste') is not null then raise exception 'Credencial revogada ainda aceita';end if;
end;$$;
rollback;
